import{readFileSync,writeFileSync}from'node:fs';import{createProblemExecutor}from'../../../src/analyze/execute-problem.ts';import{d1Observables,compareD1}from'./observables.ts';
const input=process.argv[2],baseline=process.argv[3],out=process.argv[4],request=JSON.parse(readFileSync(input,'utf8'));let removed=0;
for(const i of request.instances)if(i.id.startsWith('run-'))i.model.data.inductanceH=i.model.data.inductanceH.filter(([a,b]:number[])=>{if(a!==b){removed++;return false;}return true;});
if(!removed)throw Error('NO_PHYSICAL_SECTION_MUTUALS');const r=createProblemExecutor(true)({kind:'frequency-network',request});if(r.status!=='complete')throw Error(JSON.stringify(r.diagnostics));const ref=JSON.parse(readFileSync(baseline,'utf8')),comparison=compareD1(d1Observables(r),d1Observables(ref));if(comparison.status!=='fail'||comparison.magnetic<=.08)throw Error('NEGATIVE_NOT_DETECTED');writeFileSync(out,JSON.stringify({removed,comparison,result:r,scope:'Intentionally broken TEST result: physical section mutual L removed; R, C, local L, geometry, ports and loads unchanged; never production admission'}));console.log(comparison);
